import json
A=[[2,2,2,2],[2,0,0,0],[2,0,0,2],[2,0,2,2]]
out=[[0]*19 for _ in range(19)]
placements=[]
for i in range(4):
 for j in range(4):
  if A[i][j]==2:
   placements.append((i,j))
   for a in range(4):
    for b in range(4):
     out[5*i+a][5*j+b]=A[a][b]
   # Mark the location in each copied motif that encodes this macro-grid position.
   out[5*i+i][5*j+j]=8
assert len(out)==19 and all(len(row)==19 for row in out)
assert set(v for row in out for v in row) <= {0,2,8}
print('placements:',placements)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

